// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;

import org.junit.jupiter.api.Test;

class PackedContinuationParetoArenaTest {

	@Test
	void continuationIdentityDefaultsToExactEqualityAcrossSuffixObservableFields() {
		PackedSearchBudget budget = new PackedSearchBudget(PackedPlannerLimits.unbounded());
		PackedContinuationKeyArena keys = new PackedContinuationKeyArena(budget);

		int baseline = key(keys, 7, 11, 13);

		assertEquals(baseline, key(keys, 7, 11, 13), "an identical continuation must intern once");
		assertNotEquals(baseline, key(keys, 7, 12, 13), "ordered-prefix identity is suffix-observable");
		assertNotEquals(baseline, key(keys, 7, 11, 14), "evidence identity is suffix-observable");
		assertEquals(3, keys.size());
	}

	@Test
	void paretoRetentionKeepsTradeoffsAndUsesLineageSafeIntervalDominance() {
		PackedSearchBudget budget = new PackedSearchBudget(PackedPlannerLimits.unbounded());
		PackedContinuationKeyArena keys = new PackedContinuationKeyArena(budget);
		PackedCostVectorArena vectors = new PackedCostVectorArena();
		PackedCandidateArena candidates = new PackedCandidateArena(budget);
		PackedParetoFrontierArena frontiers = new PackedParetoFrontierArena(budget, candidates, vectors);
		int continuationKeyId = key(keys, 3, 17, 19);

		int fastCpu = candidate(candidates, continuationKeyId, exact(vectors, 2.0d, 20.0d));
		int lowMemory = candidate(candidates, continuationKeyId, exact(vectors, 20.0d, 2.0d));
		int worse = candidate(candidates, continuationKeyId, exact(vectors, 30.0d, 30.0d));
		int duplicate = candidate(candidates, continuationKeyId, exact(vectors, 2.0d, 20.0d));

		assertEquals(PackedParetoFrontierArena.OfferResult.INSERTED, frontiers.offer(3, continuationKeyId, fastCpu));
		assertEquals(PackedParetoFrontierArena.OfferResult.INSERTED, frontiers.offer(3, continuationKeyId, lowMemory));
		assertEquals(PackedParetoFrontierArena.OfferResult.DOMINATED, frontiers.offer(3, continuationKeyId, worse));
		assertEquals(PackedParetoFrontierArena.OfferResult.DUPLICATE,
				frontiers.offer(3, continuationKeyId, duplicate));
		assertEquals(2, frontiers.size(3, continuationKeyId));

		int sameLineageBetter = candidate(candidates, continuationKeyId,
				interval(vectors, 1.0d, 2.0d, 3.0d, 23, 1.0d, 2.0d, 3.0d, 23));
		int sameLineageWorse = candidate(candidates, continuationKeyId,
				interval(vectors, 2.0d, 3.0d, 4.0d, 23, 2.0d, 3.0d, 4.0d, 23));
		int independentOverlap = candidate(candidates, continuationKeyId,
				interval(vectors, 2.0d, 3.0d, 4.0d, 29, 2.0d, 3.0d, 4.0d, 29));

		assertEquals(PackedParetoFrontierArena.OfferResult.INSERTED,
				frontiers.offer(4, continuationKeyId, sameLineageBetter));
		assertEquals(PackedParetoFrontierArena.OfferResult.DOMINATED,
				frontiers.offer(4, continuationKeyId, sameLineageWorse));
		assertEquals(PackedParetoFrontierArena.OfferResult.INSERTED,
				frontiers.offer(4, continuationKeyId, independentOverlap),
				"overlapping intervals from independent lineages are not a correctness prune");
	}

	@Test
	void dominatingCandidateAtomicallyReplacesOnlyProvenInferiorRows() {
		PackedSearchBudget budget = new PackedSearchBudget(PackedPlannerLimits.unbounded());
		PackedContinuationKeyArena keys = new PackedContinuationKeyArena(budget);
		PackedCostVectorArena vectors = new PackedCostVectorArena();
		PackedCandidateArena candidates = new PackedCandidateArena(budget);
		PackedParetoFrontierArena frontiers = new PackedParetoFrontierArena(budget, candidates, vectors);
		int continuationKeyId = key(keys, 5, 31, 37);
		int first = candidate(candidates, continuationKeyId, exact(vectors, 8.0d, 9.0d));
		int second = candidate(candidates, continuationKeyId, exact(vectors, 9.0d, 8.0d));
		int replacement = candidate(candidates, continuationKeyId, exact(vectors, 7.0d, 7.0d));

		assertEquals(PackedParetoFrontierArena.OfferResult.INSERTED, frontiers.offer(5, continuationKeyId, first));
		assertEquals(PackedParetoFrontierArena.OfferResult.INSERTED, frontiers.offer(5, continuationKeyId, second));
		assertEquals(PackedParetoFrontierArena.OfferResult.REPLACED_BY_PROOF,
				frontiers.offer(5, continuationKeyId, replacement));
		assertEquals(1, frontiers.size(5, continuationKeyId));
		assertEquals(replacement, frontiers.candidateId(5, continuationKeyId, 0));
	}

	private static int key(PackedContinuationKeyArena keys, int logicalCellId, int orderIdentityId,
			int evidenceStateId) {
		return keys.intern(logicalCellId, 2, 3, 5, 7, 9, orderIdentityId, evidenceStateId, 17,
				1, 2, 19, 23,
				PackedCostAlgebra.CompositionMode.SEQUENTIAL_SUM);
	}

	private static int candidate(PackedCandidateArena candidates, int continuationKeyId, int costVectorId) {
		return candidates.append(1, continuationKeyId, 2, costVectorId, 0, 0, 1, 1.0d);
	}

	private static int exact(PackedCostVectorArena vectors, double cpu, double memory) {
		vectors.resetBuilderToZero();
		vectors.setBuilderExact(PackedCostDimensionRegistry.STEADY_STATE_CPU_WORK, cpu);
		vectors.setBuilderExact(PackedCostDimensionRegistry.PEAK_MEMORY_BYTES, memory);
		return vectors.internBuilder();
	}

	private static int interval(PackedCostVectorArena vectors, double cpuLower, double cpuPoint, double cpuUpper,
			int cpuLineage, double memoryLower, double memoryPoint, double memoryUpper, int memoryLineage) {
		vectors.resetBuilderToZero();
		vectors.setBuilderInterval(PackedCostDimensionRegistry.STEADY_STATE_CPU_WORK, cpuLower, cpuPoint, cpuUpper,
				cpuLineage);
		vectors.setBuilderInterval(PackedCostDimensionRegistry.PEAK_MEMORY_BYTES, memoryLower, memoryPoint,
				memoryUpper, memoryLineage);
		return vectors.internBuilder();
	}
}
